{
  "name": "opencode-github-release",
  "version": "0.6.0",
  "description": "OpenCode plugin to create git tags and publish GitHub releases with semantic versioning.",
  "repository": {
    "type": "git",
    "url": "https://github.com/amestsantim/opencode-github-release"
  },
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup src/index.ts src/release.ts --format esm --dts --clean",
    "dev": "tsup src/index.ts src/release.ts --format esm --dts --watch",
    "typecheck": "tsc --noEmit",
    "test": "npm run build && node --test test/*.test.js",
    "check": "npm run typecheck && npm run test && npm pack --dry-run",
    "prepublishOnly": "npm run check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "release",
    "github"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.29",
    "@opencode/plugin": "^2.0.24"
  },
  "devDependencies": {
    "@types/node": "^25.0.10",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3"
  }
}
